export type TicketAssignment = {
  "id": unknown;
  "type": string;
  "user": unknown;
  "role": unknown;
};

/** Minimal person serializer for embedding in ticket responses. */
export type TicketPerson = {
  "id": string;
  "name": string;
  "distinct_ids": Array<string>;
  "properties": Record<string, Record<string, unknown>>;
  "created_at": string;
  "is_identified": boolean;
};

/** * `new` - New
* `open` - Open
* `pending` - Pending
* `on_hold` - On hold
* `resolved` - Resolved */
export type TicketStatusEnum = "new" | "open" | "pending" | "on_hold" | "resolved";

export type TicketView = {
  "id": string;
  "short_id": string;
  "name": string;
  "filters"?: Record<string, Record<string, unknown>>;
  "created_at": string;
  "created_by": Record<string, unknown>;
};

export type TileLayoutBox = {
  "x"?: number;
  "y"?: number;
  "w"?: number;
  "h"?: number;
};

export type TileLayouts = {
  "sm"?: Record<string, unknown>;
  "xs"?: Record<string, unknown>;
};

export type TimeRange = {
  "date_from": string;
  "date_to": string;
};

export type TimeWindowMode = "strict_calendar_dates" | "24_hour_windows";

export type TimelineEntry = {
  "events": Array<EventType>;
  "recording_duration_s"?: Record<string, unknown>;
  "sessionId"?: Record<string, unknown>;
};

